import sys

MOD = 998244353


def prime_factors(x):
    factors = []
    d = 2
    while d * d <= x:
        if x % d == 0:
            e = 0
            while x % d == 0:
                x //= d
                e += 1
            factors.append((d, e))
        d += 1
    if x > 1:
        factors.append((x, 1))
    return factors


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    by_prime = {}
    for i, x in enumerate(a):
        for p, e in prime_factors(x):
            by_prime.setdefault(p, [0] * (n - 1))[i] = e

    answer = 1
    for p, exponents in by_prime.items():
        # A state stores the current exponent height and the minimum height
        # seen so far. Subtracting that minimum enforces the global gcd=1.
        dp = {(0, 0): 1}
        for e in exponents:
            ndp = {}
            if e == 0:
                for (h, low), value in dp.items():
                    key = (h, low)
                    ndp[key] = (ndp.get(key, 0) + value * pow(p, h - low, MOD)) % MOD
            else:
                for (h, low), value in dp.items():
                    for nh in (h + e, h - e):
                        nl = min(low, nh)
                        key = (nh, nl)
                        ndp[key] = (ndp.get(key, 0) + value * pow(p, nh - nl, MOD)) % MOD
            dp = ndp

        factor = sum(dp.values()) % MOD
        answer = answer * factor % MOD

    print(answer)


if __name__ == "__main__":
    main()

