import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    values = data[1:1 + n]
    limit = max(values)

    # Smallest prime factor for every number up to the maximum input value.
    spf = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if spf[p] == p:
            for multiple in range(p * p, limit + 1, p):
                if spf[multiple] == multiple:
                    spf[multiple] = p

    nim_sum = 0
    for value in values:
        grundy = 0
        while value > 1:
            grundy += 1
            value //= spf[value]
        nim_sum ^= grundy

    print('Anna' if nim_sum else 'Bruno')

