from typing import List
import heapq

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        for i, (x, y) in enumerate(conflictingPairs):
            a, b = sorted((x, y))
            by_right[b].append((a, i))

        heap = []
        gains = [0] * len(conflictingPairs)
        total = 0

        for right in range(1, n + 1):
            for left, idx in by_right[right]:
                heapq.heappush(heap, (-left, idx))

            largest = -heap[0][0] if heap else 0
            total += right - largest

            if heap:
                first = heapq.heappop(heap)
                second_largest = -heap[0][0] if heap else 0
                gains[first[1]] += largest - second_largest
                heapq.heappush(heap, first)

        return total + max(gains)

