        for i,(x,y) in enumerate(conflictingPairs):
            a,b=sorted((x,y))
            by_right[b].append((a,i))
        heap=[]
        gain=[0]*len(conflictingPairs)
        base=0
        for r in range(1,n+1):
            for a,i in by_right[r]:
                heapq.heappush(heap,(-a,i))
            top=heap[0][0]*-1 if heap else 0
            base += r-top
            if heap:
                first=heapq.heappop(heap)
                second=(-heap[0][0]) if heap else 0
                gain[first[1]] += top-second
                heapq.heappush(heap,first)
        return base+max(gain)

