import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n, m, q = next(it), next(it), next(it)
    edges = []
    for _ in range(m):
        a, b, c = next(it) - 1, next(it) - 1, next(it)
        edges.append((a, b, c))

    queries = []
    closed = [False] * m
    for _ in range(q):
        t = next(it)
        if t == 1:
            idx = next(it) - 1
            queries.append((1, idx))
            closed[idx] = True
        else:
            x, y = next(it) - 1, next(it) - 1
            queries.append((2, x, y))

    inf = 10**30
    dist = [[inf] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for idx, (a, b, c) in enumerate(edges):
        if not closed[idx]:
            dist[a][b] = dist[b][a] = c

    # All-pairs shortest paths with the roads remaining after all closures.
    for k in range(n):
        row_k = dist[k]
        for i in range(n):
            row_i = dist[i]
            dik = row_i[k]
            if dik == inf:
                continue
            for j in range(n):
                candidate = dik + row_k[j]
                if candidate < row_i[j]:
                    row_i[j] = candidate

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            value = dist[query[1]][query[2]]
            answers.append(-1 if value == inf else value)
        else:
            a, b, c = edges[query[1]]
            to_a = [dist[i][a] for i in range(n)]
            to_b = [dist[i][b] for i in range(n)]
            for i in range(n):
                row = dist[i]
                via_a = to_a[i] + c
                via_b = to_b[i] + c
                for j in range(n):
                    candidate = via_a + to_b[j]
                    if candidate < row[j]:
                        row[j] = candidate
                    candidate = via_b + to_a[j]
                    if candidate < row[j]:
                        row[j] = candidate

    print("\n".join(map(str, reversed(answers))))

if __name__ == "__main__":
    main()

