def solve():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n=data[0]; a=data[1:]
    pref=[0]*(n+1); seen=set()
    for k,x in enumerate(a,1):
        seen.add(x); pref[k]=len(seen)
    suff=[0]*(n+2); seen=set()
    for k in range(n,0,-1):
        seen.add(a[k-1]); suff[k]=len(seen)
    size=1
    while size<n+1: size*=2
    neg=-10**9
    mx=[neg]*(2*size); lazy=[0]*(2*size)
    def push(v):
        z=lazy[v]
        if z:
            for c in (v*2,v*2+1):
                mx[c]+=z; lazy[c]+=z
            lazy[v]=0
    def add(v,l,r,ql,qr,x):
        if ql<=l and r<=qr:
            mx[v]+=x; lazy[v]+=x; return
        push(v); m=(l+r)//2
        if ql<=m: add(v*2,l,m,ql,qr,x)
        if qr>m: add(v*2+1,m+1,r,ql,qr,x)
        mx[v]=max(mx[v*2],mx[v*2+1])
    def setval(v,l,r,p,x):
        if l==r: mx[v]=x; lazy[v]=0; return
        push(v); m=(l+r)//2
        if p<=m: setval(v*2,l,m,p,x)
        else: setval(v*2+1,m+1,r,p,x)
        mx[v]=max(mx[v*2],mx[v*2+1])
    last=[0]*(n+1); ans=0
    for j in range(2,n):
