class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Pascal's triangle: combinations modulo MOD.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for i in range(1, n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # If a number has c set bits, it takes one operation to become c.
        # Thus it is reducible within k operations exactly when c itself
        # reaches 1 in fewer than k operations.
        good = [False] * (n + 1)
        for c in range(1, n + 1):
            x = c
            steps = 0
            while x != 1:
                x = x.bit_count()
                steps += 1
            good[c] = steps < k

        # Scan s from left to right. Whenever s has a 1, count numbers that
        # first differ here (putting 0), then freely choose remaining bits.
        ans = 0
        used = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                for c in range(1, n + 1):
                    if good[c]:
                        need = c - used
                        if 0 <= need <= remaining:
                            ans += comb[remaining][need]
                used += 1

        return ans % MOD

