import sys
from collections import deque

def main():
    input = sys.stdin.readline
    n = int(input())
    graph = [input().strip() for _ in range(n)]

    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outmask = [[0] * 26 for _ in range(n)]
    for u in range(n):
        for v, ch in enumerate(graph[u]):
            if ch != '-':
                c = ord(ch) - 97
                incoming[v][c].append(u)
                outmask[u][c] |= 1 << v

    dist = [[-1] * n for _ in range(n)]
    q = deque()
    for i in range(n):
        dist[i][i] = 0
        q.append((i, i))
    for i in range(n):
        for j, ch in enumerate(graph[i]):
            if ch != '-' and dist[i][j] == -1:
                dist[i][j] = 1
                q.append((i, j))

    while q:
        x, y = q.popleft()
        nd = dist[x][y] + 2
        for c in range(26):
            us = incoming[x][c]
            vs_mask = outmask[y][c]
            if not us or not vs_mask:
                continue
            for u in us:
                row = dist[u]
                candidates = vs_mask
                # Filter out all pairs already reached.
                for v in range(n):
                    if row[v] != -1:
                        candidates &= ~(1 << v)
                while candidates:
                    bit = candidates & -candidates
                    v = bit.bit_length() - 1
                    row[v] = nd
                    q.append((u, v))
                    candidates -= bit

    print('\n'.join(' '.join(map(str, row)) for row in dist))

if __name__ == '__main__':
    main()

