from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        total = n * m
        dirs = [(-1, 1), (1, 1), (1, -1), (-1, -1)]  # clockwise order
        answer = 0

        for d, (dr, dc) in enumerate(dirs):
            rows = range(n) if dr > 0 else range(n - 1, -1, -1)
            cols = range(m) if dc > 0 else range(m - 1, -1, -1)
            order = [r * m + c for r in rows for c in cols]
            straight = [[0, 0] for _ in range(total)]

            # Longest valid prefix from a 1, moving only in direction d.
            for p in order:
                r, c = divmod(p, m)
                if grid[r][c] == 1:
                    straight[p][1] = max(straight[p][1], 1)
                for parity in (0, 1):
                    length = straight[p][parity]
                    if not length:
                        continue
                    answer = max(answer, length)
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m:
                        expected = 2 if parity == 1 else 0
                        if grid[nr][nc] == expected:
                            q = nr * m + nc
                            new_parity = (length + 1) & 1
                            if length + 1 > straight[q][new_parity]:
                                straight[q][new_parity] = length + 1

            # Seed paths that turn clockwise once, then propagate in that direction.
            tr, tc = dirs[(d + 1) % 4]
            turned = [[0, 0] for _ in range(total)]
            for p in range(total):
                r, c = divmod(p, m)
                for parity in (0, 1):
                    length = straight[p][parity]
                    if not length:
                        continue
                    nr, nc = r + tr, c + tc
                    if 0 <= nr < n and 0 <= nc < m:
                        expected = 2 if parity == 1 else 0
                        if grid[nr][nc] == expected:
                            q = nr * m + nc
                            new_parity = (length + 1) & 1
                            if length + 1 > turned[q][new_parity]:
                                turned[q][new_parity] = length + 1

            rows = range(n) if tr > 0 else range(n - 1, -1, -1)
            cols = range(m) if tc > 0 else range(m - 1, -1, -1)
            for r in rows:
                for c in cols:
                    p = r * m + c
                    for parity in (0, 1):
                        length = turned[p][parity]
                        if not length:
                            continue
                        answer = max(answer, length)
                        nr, nc = r + tr, c + tc
                        if 0 <= nr < n and 0 <= nc < m:
                            expected = 2 if parity == 1 else 0
                            if grid[nr][nc] == expected:
                                q = nr * m + nc
                                new_parity = (length + 1) & 1
                                if length + 1 > turned[q][new_parity]:
                                    turned[q][new_parity] = length + 1

        return answer

