from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = (n + 1) // 2
        evens = n // 2

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        total = fact[odds] * fact[evens] * (2 if odds == evens else 1)
        if k > total:
            return []

        unused = set(range(1, n + 1))
        rem_odd, rem_even = odds, evens
        answer = []
        previous_parity = None

        for pos in range(n):
            for value in sorted(unused):
                parity = value % 2
                if previous_parity is not None and parity == previous_parity:
                    continue

                odd_left = rem_odd - (parity == 1)
                even_left = rem_even - (parity == 0)
                positions_left = n - pos - 1

                if positions_left == 0:
                    ways = int(odd_left == 0 and even_left == 0)
                else:
                    next_parity = 1 - parity
                    needed_odd = ((positions_left + 1) // 2
                                  if next_parity == 1 else positions_left // 2)
                    needed_even = positions_left - needed_odd
                    if odd_left == needed_odd and even_left == needed_even:
                        ways = fact[odd_left] * fact[even_left]
                    else:
                        ways = 0

                if k > ways:
                    k -= ways
                else:
                    answer.append(value)
                    unused.remove(value)
                    rem_odd, rem_even = odd_left, even_left
                    previous_parity = parity
                    break
            else:
                return []

        return answer

