class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        p10 = [1] * n
        for i in range(1, n):
            p10[i] = (p10[i - 1] * 10) % k

        weights = [0] * h
        for i in range(h):
            j = n - 1 - i
            weights[i] = p10[i] if i == j else (p10[i] + p10[j]) % k

        # can[i]: bit r is set iff the positions i..h-1 can contribute
        # residue r modulo k.
        can = [0] * (h + 1)
        can[h] = 1  # empty suffix contributes zero
        for i in range(h - 1, -1, -1):
            w = weights[i]
            nxt = can[i + 1]
            reachable = 0
            for r in range(k):
                if (nxt >> r) & 1:
                    for d in range(10):
                        reachable |= 1 << ((r + d * w) % k)
            can[i] = reachable

        chosen = []
        remainder = 0
        for i, w in enumerate(weights):
            first_digit = 1 if i == 0 else 0
            for d in range(9, first_digit - 1, -1):
                new_remainder = (remainder + d * w) % k
                needed = (-new_remainder) % k
                if (can[i + 1] >> needed) & 1:
                    chosen.append(str(d))
                    remainder = new_remainder
                    break

        left = ''.join(chosen)
        return left + (left[:-1][::-1] if n % 2 else left[::-1])

