from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        next_greater = [n] * n
        stack = []
        for i, value in enumerate(nums):
            while stack and nums[stack[-1]] <= value:
                next_greater[stack.pop()] = i
            stack.append(i)

        prefix = [0] * (n + 1)
        for i, value in enumerate(nums):
            prefix[i + 1] = prefix[i] + value

        levels = n.bit_length()
        jumps = [next_greater]
        jump_costs = [[
            nums[i] * (next_greater[i] - i) - (prefix[next_greater[i]] - prefix[i])
            if next_greater[i] < n else 0
            for i in range(n)
        ]]

        for _ in range(1, levels):
            prev_jump = jumps[-1]
            prev_cost = jump_costs[-1]
            curr_jump = [n] * n
            curr_cost = [0] * n
            for i in range(n):
                mid = prev_jump[i]
                if mid < n:
                    curr_jump[i] = prev_jump[mid]
                    curr_cost[i] = prev_cost[i] + prev_cost[mid]
            jumps.append(curr_jump)
            jump_costs.append(curr_cost)

        def required_operations(left: int, right: int) -> int:
            cur = left
            total = 0
            for level in range(levels - 1, -1, -1):
                dest = jumps[level][cur]
                if dest <= right:
                    total += jump_costs[level][cur]
                    cur = dest
            total += nums[cur] * (right + 1 - cur) - (prefix[right + 1] - prefix[cur])
            return total

        answer = 0
        right = 0
        for left in range(n):
            if right < left:
                right = left
            while right + 1 < n and required_operations(left, right + 1) <= k:
                right += 1
            answer += right - left + 1
        return answer

