from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        a, b, c = p.split('*')

        def occurrences(t):
            if not t:
                return list(range(n + 1))
            m = len(t)
            lps = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = lps[j - 1]
                if t[i] == t[j]:
                    j += 1
                    lps[i] = j

            found = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = lps[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    found.append(i - m + 1)
                    j = lps[j - 1]
            return found

        starts_a = occurrences(a)
        starts_b = occurrences(b)
        starts_c = occurrences(c)
        answer = n + 1

        for x in starts_a:
            ib = bisect_left(starts_b, x + len(a))
            if ib == len(starts_b):
                continue
            y = starts_b[ib]
            ic = bisect_left(starts_c, y + len(b))
            if ic == len(starts_c):
                continue
            z = starts_c[ic]
            answer = min(answer, z + len(c) - x)

        return -1 if answer == n + 1 else answer

