from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Iterative postorder DFS; reversing the push order preserves increasing
        # child order when nodes are popped.
        order = []
        stack = [(0, False)]
        while stack:
            u, done = stack.pop()
            if done:
                order.append(u)
            else:
                stack.append((u, True))
                for v in reversed(children[u]):
                    stack.append((v, False))

        end = [0] * n
        for i, u in enumerate(order):
            end[u] = i

        # In postorder, each child's size is complete before it is added to
        # its parent.
        size = [1] * n
        for u in order:
            if parent[u] != -1:
                size[parent[u]] += size[u]

        a = [s[u] for u in order]
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - radius >= 0 and i + radius < n and a[i - radius] == a[i + radius]:
                radius += 1
            odd[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius + 1, i + radius - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - radius - 1 >= 0 and i + radius < n and a[i - radius - 1] == a[i + radius]:
                radius += 1
            even[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius, i + radius - 1

        answer = [False] * n
        for u in range(n):
            r = end[u]
            length = size[u]
            l = r - length + 1
            if length % 2:
                center = (l + r) // 2
                answer[u] = odd[center] >= length // 2 + 1
            else:
                center = (l + r + 1) // 2
                answer[u] = even[center] >= length // 2
        return answer

