import sys
import math
import bisect

N = int(sys.stdin.buffer.readline())
M = math.isqrt(N)

sieve = bytearray(b'\x01') * (M + 1)
if M >= 0:
    sieve[0] = 0
if M >= 1:
    sieve[1] = 0
for p in range(2, math.isqrt(M) + 1):
    if sieve[p]:
        start = p * p
        sieve[start:M + 1:p] = b'\x00' * (((M - start) // p) + 1)

primes = [i for i in range(2, M + 1) if sieve[i]]
answer = 0

# Numbers of the form p^2 q^2, for distinct primes p < q.
for i, p in enumerate(primes):
    j = bisect.bisect_right(primes, M // p)
    answer += max(0, j - i - 1)
    if j <= i + 1:
        break

# Numbers of the form p^8.
for p in primes:
    if p ** 8 <= N:
        answer += 1
    else:
        break

print(answer)

